SELECT ca_bill.ca_state AS bill_state, ca_ship.ca_state AS ship_state, COUNT(DISTINCT cs.cs_order_number) AS num_orders, SUM(cs.cs_ext_sales_price) AS total_sales, SUM(cs.cs_net_profit) AS total_profit, AVG(cs.cs_quantity) AS avg_quantity, SUM(cs.cs_ext_discount_amt) AS total_discount FROM catalog_sales cs JOIN customer_address ca_bill ON cs.cs_bill_addr_sk = ca_bill.ca_address_sk JOIN customer_address ca_ship ON cs.cs_ship_addr_sk = ca_ship.ca_address_sk WHERE cs.cs_wholesale_cost > 60 AND cs.cs_quantity >= 20 AND cs.cs_ext_ship_cost BETWEEN 500 AND 1500 AND ca_bill.ca_country = 'United States' AND ca_ship.ca_country = 'United States' GROUP BY ca_bill.ca_state, ca_ship.ca_state HAVING SUM(cs.cs_ext_sales_price) > 10000 ORDER BY total_profit DESC LIMIT 20
